<?php $submitted=(bool)$transaction['return_id'];$finished=$transaction['status']==='completed'; ?>
<section class="panel timeline-panel"><h2>Perjalanan barang</h2><ol class="timeline"><li class="done"><span class="timeline-dot"><?=icon('check')?></span><div><strong>Peminjaman aktif</strong><p>Barang dipakai sesuai kesepakatan.</p><small><?=h(dateLabel($transaction['start_date']))?></small></div></li><li class="<?=$submitted?'done':'current'?>"><span class="timeline-dot"><?=$submitted?icon('check'):icon('box')?></span><div><strong>Pengembalian diajukan</strong><p>Peminjam menyerahkan barang kembali.</p><?php if($submitted):?><small><?=h(dateLabel($transaction['returned_at'],true))?></small><?php endif;?></div></li><li class="<?=$finished?'done':($submitted?'current':'') ?>"><span class="timeline-dot"><?=icon('check')?></span><div><strong>Pemilik mengonfirmasi</strong><p>Barang diperiksa, transaksi selesai.</p><?php if($finished):?><small><?=h(dateLabel($transaction['confirmed_at'],true))?></small><?php endif;?></div></li></ol></section>
